contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(amount <= address(c).balance);

        uint beforeBalance = address(c).balance;
        uint beforeOwnerBalance = address(this).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint afterBalance = address(c).balance;
        uint afterOwnerBalance = address(this).balance;

        assert(afterBalance == beforeBalance - amount && afterOwnerBalance == beforeOwnerBalance + amount);
    }

    receive() external payable {}
}

